\if :autorizar_actualizacion
  LOCK TABLE public.productos IN ACCESS EXCLUSIVE MODE;
\endif
CREATE TEMP TABLE pro327_resuelto ON COMMIT DROP AS
 SELECT m.*,p.id AS producto_id,p.codigo AS bd_codigo,p.codigo_inventario AS bd_inventario,
        p.codigo_sifen AS bd_sifen,p.descripcion AS bd_descripcion,
        coalesce(p.codigo=m.codigo_anterior AND p.codigo_inventario IS NOT DISTINCT FROM m.codigo_anterior
          AND p.codigo_sifen IS NOT DISTINCT FROM m.codigo_anterior,false) AS previo,
        coalesce(p.codigo=m.codigo_nuevo AND p.codigo_inventario IS NOT DISTINCT FROM m.codigo_cliente
          AND p.codigo_sifen IS NOT DISTINCT FROM m.codigo_sifen,false) AS final
 FROM pro327_mapa m LEFT JOIN public.productos p ON p.empresa_id=current_setting('pro327.empresa_uuid')::uuid
    AND p.codigo IN (m.codigo_anterior,m.codigo_nuevo);

DO $validar$
DECLARE e uuid:=current_setting('pro327.empresa_uuid')::uuid; pendientes int; aplicados int;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.empresas
    WHERE id=e AND codigo='80003314' AND razon_social='CASA MINGO S.A.'
       AND estado='ACTIVA' AND es_demo=false) THEN
  RAISE EXCEPTION 'PRO327: empresa distinta de CASA MINGO S.A.';
 END IF;
 IF (SELECT count(*) FROM pro327_mapa)<>561 OR (SELECT count(*) FROM pro327_resuelto)<>561
    OR (SELECT count(DISTINCT producto_id) FROM pro327_resuelto)<>561 THEN
  RAISE EXCEPTION 'PRO327: 561 filas del script original no corresponden a 561 UUID unicos.';
 END IF;
 IF (SELECT count(*) FROM pro327_mapa WHERE codigo_anterior<>codigo_nuevo)<>249
    OR (SELECT count(*) FROM pro327_mapa WHERE codigo_anterior<>codigo_cliente)<>254
    OR (SELECT count(*) FROM pro327_mapa WHERE motivo='DUPLICADO_REMAPEADO')<>5 THEN
  RAISE EXCEPTION 'PRO327: mapa 249/254/5 alterado.';
 END IF;
 IF EXISTS(SELECT 1 FROM pro327_mapa WHERE codigo_nuevo<>codigo_sifen
    OR char_length(codigo_nuevo)>20 OR char_length(codigo_cliente)>80
    OR motivo NOT IN ('SIN_CAMBIO','RESTAURAR_CEROS','DUPLICADO_REMAPEADO')) THEN
  RAISE EXCEPTION 'PRO327: codigo o longitud de mapa no valida.';
 END IF;
 IF EXISTS(SELECT 1 FROM pro327_mapa a JOIN pro327_mapa b
    ON a.codigo_nuevo=b.codigo_anterior WHERE a.fila_excel<>b.fila_excel) THEN
  RAISE EXCEPTION 'PRO327: destino ocupa codigo anterior de otra fila.';
 END IF;
 IF EXISTS(SELECT 1 FROM pro327_resuelto WHERE NOT (previo OR final)
    OR lower(btrim(bd_descripcion)) IS DISTINCT FROM lower(btrim(descripcion))) THEN
  RAISE EXCEPTION 'PRO327: registro diferente de lo importado. No actualizar sin revision.';
 END IF;
 IF EXISTS(SELECT 1 FROM public.productos p JOIN pro327_mapa m ON p.codigo=m.codigo_nuevo
    WHERE p.empresa_id=e AND p.id NOT IN (SELECT producto_id FROM pro327_resuelto)) THEN
  RAISE EXCEPTION 'PRO327: codigo destino ya pertenece a otro producto.';
 END IF;
 IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid='public.productos'::regclass
    AND tgname='productos_codigo_inmutable_trg' AND tgenabled='O') THEN
  RAISE EXCEPTION 'PRO327: trigger inmutable NEX-038 no esta habilitado.';
 END IF;
 IF EXISTS(SELECT 1 FROM public.productos p JOIN pro327_resuelto r ON p.empresa_id=e
    AND p.codigo='__PRO327__'||replace(r.producto_id::text,'-','')) THEN
  RAISE EXCEPTION 'PRO327: codigo temporal ocupado.';
 END IF;
 SELECT count(*) FILTER(WHERE previo AND NOT final),count(*) FILTER(WHERE final AND NOT previo)
  INTO pendientes,aplicados FROM pro327_resuelto;
 IF NOT ((pendientes=254 AND aplicados=0) OR (pendientes=0 AND aplicados=254)) THEN
  RAISE EXCEPTION 'PRO327: datos en estado mixto no contemplado: % pendientes, % corregidos',pendientes,aplicados;
 END IF;
 RAISE NOTICE 'PRO327 preflight OK. Pendientes %, corregidos %',pendientes,aplicados;
END $validar$;
-- Informe por cada fila con cambio: la vista incluye UUID real y valores anteriores.
SELECT fila_excel,producto_id,descripcion,bd_codigo,codigo_nuevo,
       bd_inventario,codigo_cliente,bd_sifen,codigo_sifen,motivo,
       CASE WHEN previo AND NOT final THEN 'PENDIENTE' ELSE 'YA_CORREGIDO' END AS estado
 FROM pro327_resuelto WHERE NOT(previo AND final) ORDER BY fila_excel;

\if :autorizar_actualizacion
  -- DDL transaccional: un error/ROLLBACK rehabilita automaticamente el trigger.
  -- Se suspende SOLAMENTE productos_codigo_inmutable_trg, nunca todos los triggers.
  DO $rol$
  BEGIN
    IF NOT (SELECT pg_has_role(current_user,c.relowner,'MEMBER') FROM pg_class c
         WHERE c.oid='public.productos'::regclass)
       AND NOT (SELECT rolsuper FROM pg_roles WHERE rolname=current_user) THEN
      RAISE EXCEPTION 'PRO327: se necesita rol propietario de public.productos.';
    END IF;
  END $rol$;
  ALTER TABLE public.productos DISABLE TRIGGER productos_codigo_inmutable_trg;
  -- Fase 1: claves temporales por UUID, solo 249 filas con codigo que cambia.
  UPDATE public.productos p SET codigo='__PRO327__'||replace(p.id::text,'-','')
  FROM pro327_resuelto r
  WHERE p.empresa_id=current_setting('pro327.empresa_uuid')::uuid
   AND p.id=r.producto_id AND previo AND NOT final
   AND r.codigo_anterior<>r.codigo_nuevo AND p.codigo=r.codigo_anterior;
  -- Fase 2: 249 destinos finales exactos, sin convertirlos a numericos.
  UPDATE public.productos p SET codigo=r.codigo_nuevo
  FROM pro327_resuelto r
  WHERE p.empresa_id=current_setting('pro327.empresa_uuid')::uuid
   AND p.id=r.producto_id
   AND r.codigo_anterior<>r.codigo_nuevo
   AND p.codigo='__PRO327__'||replace(p.id::text,'-','');
  -- Fase 3: 254 inventarios (5 duplicados originales) y 249 codigos SIFEN.
  UPDATE public.productos p SET codigo_inventario=r.codigo_cliente,codigo_sifen=r.codigo_sifen
  FROM pro327_resuelto r
  WHERE p.empresa_id=current_setting('pro327.empresa_uuid')::uuid
   AND p.id=r.producto_id
   AND (p.codigo_inventario IS DISTINCT FROM r.codigo_cliente
        OR p.codigo_sifen IS DISTINCT FROM r.codigo_sifen);
  ALTER TABLE public.productos ENABLE TRIGGER productos_codigo_inmutable_trg;
  DO $finalcheck$
  DECLARE e uuid:=current_setting('pro327.empresa_uuid')::uuid; n integer;
  BEGIN
    SELECT count(*) INTO n FROM pro327_resuelto m JOIN public.productos p
      ON p.empresa_id=e AND p.id=m.producto_id
    WHERE p.codigo=m.codigo_nuevo AND p.codigo_inventario IS NOT DISTINCT FROM m.codigo_cliente
     AND p.codigo_sifen IS NOT DISTINCT FROM m.codigo_sifen
     AND lower(btrim(p.descripcion))=lower(btrim(m.descripcion));
    IF n<>561 THEN RAISE EXCEPTION 'PRO327: solo %/561 productos validados. ROLLBACK',n; END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid='public.productos'::regclass
      AND tgname='productos_codigo_inmutable_trg' AND tgenabled='O') THEN
      RAISE EXCEPTION 'PRO327: trigger no reactivado; ROLLBACK';
    END IF;
    IF EXISTS (SELECT 1 FROM public.productos WHERE empresa_id=e AND codigo LIKE '__PRO327__%') THEN
      RAISE EXCEPTION 'PRO327: codigo temporal persistente; ROLLBACK';
    END IF;
    RAISE NOTICE 'PRO327 validacion final OK: 561 UUID, codigo, inventario, SIFEN. Trigger habilitado.';
  END $finalcheck$;
  SELECT 'PRO327_CONTROL_FINAL' AS tipo,count(*) AS filas,
    count(*) FILTER(WHERE codigo_anterior<>codigo_nuevo) AS codigo,
    count(*) FILTER(WHERE codigo_anterior<>codigo_cliente) AS inventario,
    count(*) FILTER(WHERE motivo='DUPLICADO_REMAPEADO') AS duplicados
  FROM pro327_resuelto;
  COMMIT;
  \echo 'PRO327 COMMIT: conservar salida y backup; NO reimportar productos ni stock.'
\else
  ROLLBACK;
  \echo 'PRO327 PREFLIGHT: no se modifico ningun registro persistente.'
\endif
